def transform(grid):
    from collections import Counter, deque

    starts = [1, 7, 13, 19]
    panels = [
        [[grid[r + 1][s + c] for c in range(5)] for r in range(5)]
        for s in starts
    ]
    background = Counter(
        value for row in panels[0] for value in row
    ).most_common(1)[0][0]

    marked = {
        (r, c)
        for r in range(5)
        for c in range(5)
        if panels[0][r][c] != background
    }

    # The largest connected part of the first panel is the divider.
    components = []
    unseen = set(marked)
    while unseen:
        seed = unseen.pop()
        component = {seed}
        queue = [seed]
        while queue:
            r, c = queue.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    neighbor = (r + dr, c + dc)
                    if neighbor in unseen:
                        unseen.remove(neighbor)
                        component.add(neighbor)
                        queue.append(neighbor)
        components.append(component)
    divider = max(components, key=len)

    # Label the regions on either side of the divider.
    labels = [[-1] * 5 for _ in range(5)]
    region = 0
    for r in range(5):
        for c in range(5):
            if (r, c) in divider or labels[r][c] != -1:
                continue
            labels[r][c] = region
            queue = deque([(r, c)])
            while queue:
                rr, cc = queue.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < 5 and 0 <= nc < 5
                            and (nr, nc) not in divider
                            and labels[nr][nc] == -1):
                        labels[nr][nc] = region
                        queue.append((nr, nc))
            region += 1

    # A separate mark identifies the side for panel 2; default to the
    # upper side when the divider has no separate mark.
    cues = marked - divider
    cue = next(iter(cues)) if cues else (0, 0)
    selected = labels[cue[0]][cue[1]]
    if selected == -1:
        selected = next(
            labels[r][c]
            for r in range(5)
            for c in range(5)
            if labels[r][c] != -1
        )

    output = [row[:] for row in grid]
    for r in range(5):
        for c in range(5):
            on_divider = (r, c) in divider
            side = labels[r][c]
            color2 = panels[1][r][c]
            color3 = panels[2][r][c]

            value = background
            if (on_divider or side != selected) and color3 != background:
                value = color3
            if (on_divider or side == selected) and color2 != background:
                value = color2

            output[r + 1][starts[3] + c] = value

    return output
